arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <title>Find and Book Top Doctors Instantly | MedBook</title>
  <meta name="title" content="Find and Book Top Doctors Instantly | MedBook">
  <meta name="description" content="Book doctors, dentists, and specialists near you in minutes. Compare verified reviews, check real-time availability, and schedule same-day appointments with MedBook.">

  <link rel="canonical" href="https://www.medbook.com/">

  <meta property="og:type" content="website">
  <meta property="og:url" content="https://www.medbook.com/">
  <meta property="og:title" content="Find and Book Top Doctors Instantly | MedBook">
  <meta property="og:description" content="Search by specialty, location, and insurance to book trusted healthcare providers fast.">
  <meta property="og:image" content="https://www.medbook.com/og-image.jpg">

  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://www.medbook.com/">
  <meta property="twitter:title" content="Find and Book Top Doctors Instantly | MedBook">
  <meta property="twitter:description" content="Find trusted doctors and book appointments instantly with MedBook.">
  <meta property="twitter:image" content="https://www.medbook.com/og-image.jpg">

  <meta name="geo.region" content="US">
  <meta name="geo.placename" content="United States">

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "MedicalBusiness",
        "@id": "https://www.medbook.com/#organization",
        "name": "MedBook",
        "url": "https://www.medbook.com/",
        "description": "MedBook is an online healthcare appointment marketplace connecting patients with local doctors, dentists, and specialists for same-day booking.",
        "image": "https://www.medbook.com/og-image.jpg",
        "areaServed": {
          "@type": "Country",
          "name": "United States"
        },
        "serviceType": "Healthcare appointment marketplace",
        "offers": {
          "@type": "Offer",
          "description": "Free appointment booking for patients",
          "price": "0",
          "priceCurrency": "USD"
        }
      },
      {
        "@type": "WebSite",
        "@id": "https://www.medbook.com/#website",
        "url": "https://www.medbook.com/",
        "name": "MedBook",
        "description": "Find and book top doctors instantly.",
        "publisher": {
          "@id": "https://www.medbook.com/#organization"
        },
        "potentialAction": {
          "@type": "SearchAction",
          "target": "https://www.medbook.com/search?q={search_term_string}",
          "query-input": "required name=search_term_string"
        }
      },
      {
        "@type": "FAQPage",
        "@id": "https://www.medbook.com/#faq",
        "mainEntity": [
          {
            "@type": "Question",
            "name": "Is MedBook free for patients?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Yes. MedBook is always 100% free for patients."
            }
          },
          {
            "@type": "Question",
            "name": "Can I book same-day appointments?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Yes. Many providers on MedBook offer same-day and next-day availability."
            }
          },
          {
            "@type": "Question",
            "name": "Are reviews verified?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "MedBook features verified patient reviews to help you choose providers with confidence."
            }
          }
        ]
      }
    ]
  }
  </script>

  <style>
    :root {
      --blue-600: #0066ff;
      --blue-700: #0051cc;
      --teal-500: #18b8a0;
      --teal-600: #139884;
      --bg: #ffffff;
      --bg-alt: #f5f8ff;
      --text: #11203b;
      --muted: #5f6c87;
      --border: #dbe4f5;
      --shadow: 0 10px 30px rgba(14, 53, 120, 0.08);
      --radius: 16px;
      --container: 1120px;
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.55;
      font-size: 16px;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--container), 92vw);
      margin: 0 auto;
    }

    .section { padding: 72px 0; }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: 12px 22px;
      font-weight: 600;
      cursor: pointer;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
      display: inline-flex;
      align-items: center;
      justify-content: center;
    }

    .btn:hover { transform: translateY(-1px); }

    .btn-primary {
      background: linear-gradient(135deg, var(--teal-500), var(--teal-600));
      color: #fff;
      box-shadow: 0 10px 20px rgba(24, 184, 160, 0.25);
    }

    .btn-outline {
      border: 1px solid var(--border);
      color: var(--blue-700);
      background: #fff;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 40;
      background: rgba(255, 255, 255, 0.9);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid #eef2fb;
    }

    .nav-wrap {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 18px;
    }

    .logo {
      font-size: 1.4rem;
      font-weight: 800;
      color: var(--blue-600);
      letter-spacing: .2px;
    }

    .nav {
      display: flex;
      align-items: center;
      gap: 24px;
      color: #2a3f67;
      font-weight: 500;
    }

    .nav-actions { display: flex; align-items: center; gap: 10px; }

    .menu-btn {
      display: none;
      width: 44px;
      height: 44px;
      border-radius: 12px;
      border: 1px solid var(--border);
      background: #fff;
      color: var(--blue-700);
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      cursor: pointer;
    }

    .mobile-drawer {
      position: fixed;
      top: 0;
      right: -320px;
      width: 300px;
      max-width: 90vw;
      height: 100dvh;
      background: #fff;
      box-shadow: -12px 0 30px rgba(20, 43, 87, .2);
      z-index: 70;
      padding: 90px 24px 24px;
      transition: right .25s ease;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .mobile-drawer.open { right: 0; }
    .mobile-drawer a {
      font-size: 1.08rem;
      color: #1f3357;
      padding: 8px 0;
      font-weight: 600;
    }

    .drawer-backdrop {
      position: fixed;
      inset: 0;
      background: rgba(10, 21, 46, .35);
      opacity: 0;
      pointer-events: none;
      transition: opacity .25s ease;
      z-index: 60;
    }

    .drawer-backdrop.show {
      opacity: 1;
      pointer-events: auto;
    }

    .hero {
      background:
        radial-gradient(900px 500px at 20% -10%, rgba(0, 102, 255, .11), transparent 60%),
        radial-gradient(700px 420px at 90% 0%, rgba(24, 184, 160, .13), transparent 62%),
        #fff;
      padding: 54px 0 36px;
    }

    .hero-grid {
      display: grid;
      gap: 28px;
      grid-template-columns: 1.2fr .8fr;
      align-items: center;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.08;
      letter-spacing: -0.6px;
    }

    .hero p {
      margin: 16px 0 0;
      color: var(--muted);
      font-size: 1.12rem;
      max-width: 58ch;
    }

    .hero-visual {
      background: linear-gradient(155deg, #f2f7ff, #ffffff);
      border: 1px solid var(--border);
      border-radius: 22px;
      box-shadow: var(--shadow);
      padding: 20px;
    }

    .mini-card {
      background: #fff;
      border: 1px solid #edf2fb;
      border-radius: 14px;
      padding: 12px;
      margin-bottom: 10px;
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: center;
    }

    .rating {
      background: #ebf9f5;
      color: #0b7a69;
      border-radius: 999px;
      padding: 5px 10px;
      font-size: .88rem;
      font-weight: 700;
    }

    .search-shell {
      margin-top: 34px;
      background: #fff;
      border-radius: 22px;
      border: 1px solid var(--border);
      box-shadow: 0 14px 38px rgba(14, 53, 120, .12);
      padding: 18px;
    }

    .search-form {
      display: grid;
      gap: 12px;
      grid-template-columns: 1.35fr 1fr auto;
      align-items: center;
      position: relative;
    }

    .input-wrap {
      position: relative;
    }

    .search-input, .location-input {
      width: 100%;
      height: 56px;
      border-radius: 14px;
      border: 1px solid #d8e3f7;
      padding: 0 14px;
      font-size: 1rem;
      transition: border-color .2s ease, box-shadow .2s ease;
    }

    .search-input:focus, .location-input:focus {
      outline: none;
      border-color: var(--blue-600);
      box-shadow: 0 0 0 3px rgba(0, 102, 255, .14);
    }

    .search-btn {
      height: 56px;
      min-width: 144px;
      font-size: 1rem;
    }

    .suggestions {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: var(--shadow);
      overflow: hidden;
      display: none;
      z-index: 20;
    }

    .suggestions.show { display: block; }

    .suggestion-item {
      padding: 11px 12px;
      cursor: pointer;
      border-bottom: 1px solid #eff4fd;
      font-size: .97rem;
      color: #1f3357;
    }

    .suggestion-item:last-child { border-bottom: 0; }
    .suggestion-item:hover, .suggestion-item.active { background: #f3f7ff; }

    .stats {
      background: var(--bg-alt);
      border-top: 1px solid #e9effb;
      border-bottom: 1px solid #e9effb;
      padding: 28px 0;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }

    .stat {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 16px;
      text-align: center;
    }

    .stat strong {
      display: block;
      font-size: 1.35rem;
      color: var(--blue-700);
      margin-bottom: 4px;
    }

    h2 {
      margin: 0;
      font-size: clamp(1.6rem, 3vw, 2.3rem);
      letter-spacing: -.3px;
    }

    .section-lead {
      color: var(--muted);
      margin: 12px 0 0;
      max-width: 68ch;
    }

    .specialties-grid {
      margin-top: 26px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }

    .specialty-card {
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 16px;
      display: flex;
      align-items: center;
      gap: 12px;
      background: #fff;
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
    }

    .specialty-card:hover {
      transform: translateY(-2px);
      box-shadow: var(--shadow);
      border-color: #c7d7f3;
    }

    .icon {
      width: 42px;
      height: 42px;
      border-radius: 11px;
      background: #ecf4ff;
      color: var(--blue-700);
      display: grid;
      place-items: center;
      font-size: 1.2rem;
      flex-shrink: 0;
    }

    .steps {
      margin-top: 26px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }

    .step {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      padding: 20px;
    }

    .step-num {
      width: 34px;
      height: 34px;
      border-radius: 999px;
      display: grid;
      place-items: center;
      font-weight: 800;
      color: #fff;
      background: linear-gradient(135deg, var(--blue-600), #4d88ff);
      margin-bottom: 12px;
    }

    .testimonials-grid {
      margin-top: 26px;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }

    .quote {
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 18px;
      background: #fff;
    }

    .quote p { margin: 0 0 12px; color: #2a3f67; }
    .quote small { color: #667591; font-weight: 600; }

    .app-promo {
      background: linear-gradient(135deg, #0f5fe6, #0a4bb8);
      color: #fff;
      border-radius: 22px;
      padding: 32px;
      display: grid;
      grid-template-columns: 1.3fr .7fr;
      gap: 18px;
      align-items: center;
      box-shadow: 0 14px 34px rgba(12, 69, 170, .3);
    }

    .badge-row { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 16px; }
    .store {
      border: 1px solid rgba(255, 255, 255, .45);
      color: #fff;
      border-radius: 10px;
      padding: 10px 14px;
      font-weight: 600;
      background: rgba(255,255,255,.08);
    }

    footer {
      background: #071735;
      color: #dae5ff;
      padding: 56px 0 34px;
      margin-top: 70px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .footer-col h3 {
      margin: 0 0 10px;
      color: #fff;
      font-size: 1rem;
    }

    .footer-col a {
      display: block;
      color: #d2defb;
      margin: 8px 0;
      font-size: .95rem;
    }

    .copyright {
      margin-top: 26px;
      border-top: 1px solid rgba(202, 218, 255, .2);
      padding-top: 18px;
      color: #c8d8ff;
      font-size: .92rem;
    }

    @media (max-width: 960px) {
      .hero-grid,
      .app-promo { grid-template-columns: 1fr; }

      .specialties-grid,
      .steps,
      .testimonials-grid,
      .stats-grid,
      .footer-grid { grid-template-columns: repeat(2, 1fr); }

      .search-form { grid-template-columns: 1fr; }
      .search-btn { width: 100%; }
    }

    @media (max-width: 760px) {
      .nav, .nav-actions { display: none; }
      .menu-btn { display: inline-flex; }
      .section { padding: 58px 0; }
      .hero { padding-top: 36px; }
    }

    @media (max-width: 560px) {
      .specialties-grid,
      .steps,
      .testimonials-grid,
      .stats-grid,
      .footer-grid { grid-template-columns: 1fr; }

      .search-shell { padding: 14px; }
      .app-promo { padding: 24px; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container nav-wrap">
      <a href="index.html" class="logo" aria-label="MedBook Home">MedBook</a>
      <nav class="nav" aria-label="Main navigation">
        <a href="#specialties">Browse</a>
        <a href="#footer-help">Help</a>
        <a href="#">Log In</a>
        <a href="#" class="btn btn-primary" style="padding: 10px 18px;">Sign Up</a>
      </nav>
      <div class="nav-actions">
        <a href="#" class="btn btn-outline">Log In</a>
        <a href="#" class="btn btn-primary">Sign Up</a>
      </div>
      <button class="menu-btn" id="menuToggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobileDrawer">☰</button>
    </div>
  </header>

  <div class="drawer-backdrop" id="drawerBackdrop"></div>
  <aside class="mobile-drawer" id="mobileDrawer" aria-hidden="true">
    <a href="#specialties">Browse</a>
    <a href="#">Log In</a>
    <a href="#" class="btn btn-primary" style="margin-top: 6px;">Sign Up</a>
  </aside>

  <main>
    <section class="hero" id="hero">
      <div class="container">
        <div class="hero-grid">
          <div>
            <h1>Find and book top doctors instantly</h1>
            <p>Search by specialty, condition, doctor name, location, and insurance. Compare verified reviews and book same-day appointments in minutes — always free for patients.</p>
          </div>
          <div class="hero-visual" aria-hidden="true">
            <div class="mini-card">
              <div>
                <strong>Dr. Angela Park</strong>
                <div style="color:#5f6c87;font-size:.92rem;">Dermatologist · 1.2 mi</div>
              </div>
              <span class="rating">★ 4.9</span>
            </div>
            <div class="mini-card">
              <div>
                <strong>Same-day slots</strong>
                <div style="color:#5f6c87;font-size:.92rem;">Today 1:30 PM · 3:15 PM</div>
              </div>
              <span class="rating">Fast</span>
            </div>
            <div class="mini-card" style="margin-bottom:0;">
              <div>
                <strong>Insurance match</strong>
                <div style="color:#5f6c87;font-size:.92rem;">In-network options found</div>
              </div>
              <span class="rating">✓</span>
            </div>
          </div>
        </div>

        <div class="search-shell" id="search" aria-label="Doctor search">
          <form class="search-form" action="search.html" method="get" id="searchForm">
            <div class="input-wrap">
              <label for="searchInput" class="sr-only" style="position:absolute;left:-10000px;">Search by specialty, condition, or provider</label>
              <input
                id="searchInput"
                name="q"
                class="search-input"
                placeholder="Search by specialty, condition, or provider"
                autocomplete="off"
                aria-autocomplete="list"
                aria-controls="suggestions"
                aria-expanded="false"
                required
              >
              <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
            </div>
            <div>
              <label for="locationInput" class="sr-only" style="position:absolute;left:-10000px;">Location</label>
              <input id="locationInput" name="location" class="location-input" placeholder="City, ZIP, or neighborhood" value="New York, NY" required>
            </div>
            <button class="btn btn-primary search-btn" type="submit">Find Doctors</button>
          </form>
        </div>
      </div>
    </section>

    <section class="stats" aria-label="Platform statistics">
      <div class="container stats-grid">
        <article class="stat"><strong>4.8M+</strong><span>verified patient reviews</span></article>
        <article class="stat"><strong>12,000+</strong><span>healthcare providers nationwide</span></article>
        <article class="stat"><strong>Same-day</strong><span>appointments available daily</span></article>
        <article class="stat"><strong>100% free</strong><span>for patients — always</span></article>
      </div>
    </section>

    <section class="section" id="specialties">
      <div class="container">
        <h2>Popular specialties</h2>
        <p class="section-lead">Browse top specialties to quickly find the right care for your needs.</p>
        <div class="specialties-grid">
          <a class="specialty-card" href="search.html?specialty=Primary%20Care"><span class="icon">🩺</span><span>Primary Care</span></a>
          <a class="specialty-card" href="search.html?specialty=Dentist"><span class="icon">🦷</span><span>Dentist</span></a>
          <a class="specialty-card" href="search.html?specialty=Dermatologist"><span class="icon">🌤️</span><span>Dermatologist</span></a>
          <a class="specialty-card" href="search.html?specialty=Psychiatrist"><span class="icon">🧠</span><span>Psychiatrist</span></a>
          <a class="specialty-card" href="search.html?specialty=Eye%20Doctor"><span class="icon">👁️</span><span>Eye Doctor</span></a>
          <a class="specialty-card" href="search.html?specialty=Orthopedic%20Surgeon"><span class="icon">🦴</span><span>Orthopedic Surgeon</span></a>
        </div>
      </div>
    </section>

    <section class="section" style="background: var(--bg-alt); border-top:1px solid #e9effb; border-bottom:1px solid #e9effb;">
      <div class="container">
        <h2>How it works</h2>
        <p class="section-lead">Get from search to confirmed appointment in minutes.</p>
        <div class="steps">
          <article class="step">
            <div class="step-num">1</div>
            <h3>Search for a provider</h3>
            <p>Enter your specialty, condition, or doctor name with location and insurance to see matched providers.</p>
          </article>
          <article class="step">
            <div class="step-num">2</div>
            <h3>Choose a time that works</h3>
            <p>View real-time availability and pick a same-day or next-day slot that fits your schedule.</p>
          </article>
          <article class="step">
            <div class="step-num">3</div>
            <h3>Book instantly</h3>
            <p>Confirm your visit in a few clicks and receive instant confirmation with appointment reminders.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="section" id="testimonials">
      <div class="container">
        <h2>Patients trust MedBook</h2>
        <div class="testimonials-grid">
          <article class="quote">
            <p>“I found a great dermatologist near my office and booked a same-day appointment during my lunch break. MedBook made it incredibly easy.”</p>
            <small>Priya M., New York, NY</small>
          </article>
          <article class="quote">
            <p>“As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!”</p>
            <small>James T., Chicago, IL</small>
          </article>
          <article class="quote">
            <p>“I was dreading finding a new dentist, but the verified reviews on MedBook gave me confidence. My appointment was exactly what I needed.”</p>
            <small>Laura K., Austin, TX</small>
          </article>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container app-promo">
        <div>
          <h2 style="margin-bottom:8px;">Your health, in your pocket</h2>
          <p style="margin:0; color:#e6efff; max-width:62ch;">Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go. Available on iOS and Android.</p>
          <ul style="margin:16px 0 0; padding-left:20px; color:#eef4ff;">
            <li>Book and manage appointments anywhere</li>
            <li>Get real-time appointment reminders</li>
            <li>Access visit history and provider details</li>
            <li>Read and leave verified reviews</li>
          </ul>
        </div>
        <div>
          <div class="badge-row">
            <a class="store" href="#" aria-label="Download on the App Store">Download on the App Store</a>
            <a class="store" href="#" aria-label="Get it on Google Play">Get it on Google Play</a>
          </div>
        </div>
      </div>
    </section>
  </main>

  <footer id="footer-help">
    <div class="container">
      <div class="footer-grid">
        <div class="footer-col">
          <h3>For Patients</h3>
          <a href="#">Find a Doctor</a>
          <a href="#">Browse Specialties</a>
          <a href="#">Read Reviews</a>
          <a href="#">Insurance Guide</a>
        </div>
        <div class="footer-col">
          <h3>For Providers</h3>
          <a href="#">List Your Practice</a>
          <a href="#">Provider Resources</a>
