  <script>
    (function () {
      const suggestionsData = [
        "Primary Care",
        "Dentist",
        "Dermatologist",
        "Psychiatrist",
        "Eye Doctor",
        "Orthopedic Surgeon",
        "Pediatrician",
        "Cardiologist",
        "OB-GYN",
        "Migraine",
        "Back pain",
        "Skin rash",
        "Dr. Angela Park"
      ];

      const searchInput = document.getElementById('searchInput');
      const suggestions = document.getElementById('suggestions');
      let activeIndex = -1;
      let currentItems = [];

      function renderSuggestions(items) {
        currentItems = items;
        activeIndex = -1;

        if (!items.length) {
          suggestions.classList.remove('show');
          searchInput.setAttribute('aria-expanded', 'false');
          suggestions.innerHTML = '';
          return;
        }

        suggestions.innerHTML = items
          .map((item, index) => `<div class="suggestion-item" role="option" data-index="${index}">${item}</div>`)
          .join('');

        suggestions.classList.add('show');
        searchInput.setAttribute('aria-expanded', 'true');
      }

      function filterSuggestions(value) {
        const query = value.trim().toLowerCase();
        if (!query) {
          renderSuggestions([]);
          return;
        }

        const filtered = suggestionsData
          .filter(item => item.toLowerCase().includes(query))
          .slice(0, 6);

        renderSuggestions(filtered);
      }

      searchInput.addEventListener('input', (e) => {
        filterSuggestions(e.target.value);
      });

      suggestions.addEventListener('mousedown', (e) => {
        const target = e.target.closest('.suggestion-item');
        if (!target) return;
        searchInput.value = target.textContent;
        renderSuggestions([]);
      });

      searchInput.addEventListener('keydown', (e) => {
        if (!currentItems.length) return;

        if (e.key === 'ArrowDown') {
          e.preventDefault();
          activeIndex = (activeIndex + 1) % currentItems.length;
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          activeIndex = (activeIndex - 1 + currentItems.length) % currentItems.length;
        } else if (e.key === 'Enter' && activeIndex >= 0) {
          e.preventDefault();
          searchInput.value = currentItems[activeIndex];
          renderSuggestions([]);
          return;
        } else if (e.key === 'Escape') {
          renderSuggestions([]);
          return;
        } else {
          return;
        }

        const nodes = suggestions.querySelectorAll('.suggestion-item');
        nodes.forEach((n, idx) => n.classList.toggle('active', idx === activeIndex));
      });

      document.addEventListener('click', (e) => {
        if (!e.target.closest('.input-wrap')) {
          renderSuggestions([]);
        }
      });

      const form = document.getElementById('searchForm');
      form.addEventListener('submit', (e) => {
        e.preventDefault();
        const params = new URLSearchParams(new FormData(form));
        window.location.href = `search.html?${params.toString()}`;
      });

      const menuToggle = document.getElementById('menuToggle');
      const mobileDrawer = document.getElementById('mobileDrawer');
      const drawerBackdrop = document.getElementById('drawerBackdrop');

      function closeDrawer() {
        mobileDrawer.classList.remove('open');
        drawerBackdrop.classList.remove('show');
        menuToggle.setAttribute('aria-expanded', 'false');
        mobileDrawer.setAttribute('aria-hidden', 'true');
      }

      function openDrawer() {
        mobileDrawer.classList.add('open');
        drawerBackdrop.classList.add('show');
        menuToggle.setAttribute('aria-expanded', 'true');
        mobileDrawer.setAttribute('aria-hidden', 'false');
      }

      menuToggle.addEventListener('click', () => {
        const isOpen = mobileDrawer.classList.contains('open');
        if (isOpen) closeDrawer(); else openDrawer();
      });

      drawerBackdrop.addEventListener('click', closeDrawer);

      mobileDrawer.querySelectorAll('a').forEach((link) => {
        link.addEventListener('click', closeDrawer);
      });
    })();
  </script>
</body>
</html>
